import { useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";

export default function Question() {
  const [progress, setProgress] = useState(0);
  const sectionRef = useRef(null);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    window.addEventListener("resize", checkMobile, { passive: true });
    return () => window.removeEventListener("resize", checkMobile);
  }, []);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current; if (!el) return;
      const rect = el.getBoundingClientRect();
      const p = clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const title1P = ease(clamp(progress / 0.15, 0, 1));
  const cards1P = ease(clamp((progress - 0.08) / 0.20, 0, 1));
  const title2P = ease(clamp((progress - 0.35) / 0.15, 0, 1));
  const cards2P = ease(clamp((progress - 0.42) / 0.20, 0, 1));

  const questions = [
    { img: "/assets/question1.png", text: "Which segments are the most risk-prone?" },
    { img: "/assets/question2.png", text: "Where are the risk hotspots across the country?" },
    { img: "/assets/question3.png", text: "what correlations exist between risk rates and other factors?" },
  ];

  const people = [
    { label: "Truck drivers",     riskRate: "4.75%", meanAge: "30.90", img: "/assets/truck-driver.png" },
    { label: "Dark Store Workers", riskRate: "2.36%", meanAge: "24.34", img: "/assets/store.png" },
    { label: "Delivery Partners",  riskRate: "3.04%", meanAge: "27.94", img: "/assets/delivery.png" },
  ];

  const font = "'Inter','Helvetica Neue',sans-serif";

  return (
    <div ref={sectionRef} style={{ height: "400vh", position: "relative" }}>

      <div
        className="sm:h-[125vh] h-[204vh]"
        style={{
          position: "sticky", top: 0, overflow: "hidden",
          background: "black",
          display: "flex", flexDirection: "column",
          alignItems: "center", justifyContent: "center",
          // Mobile: tight side padding, smaller gap
          padding: isMobile ? "24px 16px 20px" : "48px 64px",
          gap: isMobile ? 16 : 40,
        }}
      >
        {/* Ellipse */}
        <div style={{ position: "absolute", top: 0, right: isMobile ? -200 : -430, zIndex: 0, pointerEvents: "none" }}>
          <img
            src="/assets/Ellipse.png"
            alt=""
            style={{ width: isMobile ? 500 : 900, height: isMobile ? 500 : 900 }}
          />
        </div>

        {/* ── Section 1: Questions ── */}
        <div style={{ width: "100%", maxWidth: 1300, position: "relative", zIndex: 1 }}>
          <h2
            className="sm:text-[105px] text-[36px]"
            style={{
              fontFamily: font,
              fontWeight: 700, color: "white",
              // Mobile: tighter bottom margin
              margin: isMobile ? "0 0 16px" : "0 0 32px",
              textAlign: "center", lineHeight: 1.08,
              opacity: title1P, transform: `translateY(${lerp(200, 0, title1P)}px)`,
            }}
          >
            This section{" "}
            <span style={{ fontWeight: 700 }}>answers questions like</span>
          </h2>

          <div style={{
            display: "grid",
            gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
            // Mobile: tighter gap between question cards
            gap: isMobile ? 10 : 20,
            width: "100%",
          }}>
            {questions.map((q, i) => {
              const cp = ease(clamp((cards1P * 1 - i * 0.15), 0, 1));
              return (
                <div key={i} style={{
                  backgroundImage: "linear-gradient(#1d1d1d,#212121)",
                  border: "1px solid white",
                  borderRadius: 16,
                  // Mobile: smaller padding, smaller minHeight
                  padding: isMobile ? "12px 14px" : "18px 20px",
                  display: "flex", alignItems: "center",
                  gap: isMobile ? 14 : 20,
                  minHeight: isMobile ? 72 : 110,
                  opacity: cp,
                  transform: `translateY(${lerp(30, 0, cp)}px) scale(${lerp(0.96, 1, cp)})`,
                }}>
                  <div style={{
                    // Mobile: smaller icon container
                    width: isMobile ? 52 : 78,
                    height: isMobile ? 52 : 78,
                    flexShrink: 0,
                    borderRadius: 14,
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    <img
                      src={q.img} alt=""
                      style={{
                        width: isMobile ? 80 : 150,
                        height: isMobile ? 60 : 100,
                        objectFit: "contain",
                      }}
                    />
                  </div>
                  <p style={{
                    color: "white",
                    fontSize: isMobile ? "14px" : "clamp(13px,1.05vw,17px)",
                    fontWeight: 500, margin: 0, lineHeight: 1.5,
                    fontFamily: font,
                  }}>{q.text}</p>
                </div>
              );
            })}
          </div>
        </div>

        {/* Divider */}
        <div style={{
          width: "100%", maxWidth: 1300,
          height: 1, background: "rgba(255,255,255,0.08)",
          opacity: title2P,
          position: "relative", zIndex: 1,
        }} />

        {/* ── Section 2: People ── */}
        <div style={{ width: "100%", maxWidth: 1100, position: "relative", zIndex: 1 }}>
          <h2
            className="bg-gradient-to-r from-[#cdcdcd] to-white bg-clip-text text-transparent sm:text-[105px] text-[40px]"
            style={{
              fontFamily: font,
              fontWeight: 700,
              // Mobile: tighter bottom margin
              margin: isMobile ? "0 0 14px" : "0 0 32px",
              textAlign: "center", lineHeight: 1.05,
              opacity: title2P, transform: `translateY(${lerp(24, 0, title2P)}px)`,
            }}
          >
            People in focus
          </h2>

          <div style={{
            display: "grid",
            gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
            // Mobile: tight gap
            gap: isMobile ? 10 : 20,
            width: "100%",
          }}>
            {people.map((p, i) => {
              const cp = ease(clamp((cards2P * 1 - i * 0.15), 0, 1));
              return (
                <div key={i} style={{
                  background: "rgba(255,255,255,0.06)",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: 16,
                  // Mobile: smaller padding, smaller minHeight so all 3 fit
                  padding: isMobile ? "14px 16px 0" : "28px 28px 0",
                  display: "flex", flexDirection: "column",
                  position: "relative", overflow: "hidden",
                  minHeight: isMobile ? 148 : 280,
                  opacity: cp, transform: `translateY(${lerp(30, 0, cp)}px)`,
                }}>
                  <div style={{
                    color: "#CE1010",
                    fontSize: isMobile ? "14px" : "18px",
                    fontWeight: 600,
                    marginBottom: isMobile ? 6 : 16,
                    fontFamily: font,
                  }}>{p.label}</div>

                  <div style={{
                    color: "white",
                    marginTop: isMobile ? "4px" : "12px",
                    fontSize: isMobile ? "clamp(22px,6vw,32px)" : "clamp(26px,2.8vw,42px)",
                    fontWeight: 700, lineHeight: 1, fontFamily: font,
                  }}>{p.riskRate}</div>

                  <div style={{
                    color: "white",
                    fontSize: isMobile ? 13 : 18,
                    marginTop: isMobile ? 3 : 6,
                    marginBottom: isMobile ? 8 : 20,
                    fontFamily: font,
                  }}>Risk Rate</div>

                  <div style={{
                    color: "white",
                    fontSize: isMobile ? 13 : 18,
                    marginBottom: isMobile ? 4 : 19,
                    marginTop: isMobile ? 0 : 5,
                    fontFamily: font,
                  }}>Mean Age</div>

                  <div style={{
                    color: "white",
                    fontSize: isMobile ? "clamp(22px,6vw,32px)" : "clamp(26px,2.8vw,42px)",
                    fontWeight: 700, lineHeight: 1, fontFamily: font,
                  }}>{p.meanAge}</div>

                  <div style={{
                    color: "white",
                    fontSize: isMobile ? 13 : 18,
                    marginTop: isMobile ? 3 : 8,
                    marginBottom: isMobile ? 12 : 20,
                    fontFamily: font,
                  }}>years</div>

                  <img
                    src={p.img}
                    alt={p.label}
                    style={{
                      position: "absolute",
                      bottom: -10, right: -10,
                      width: "34%", maxWidth: isMobile ? 90 : 130,
                      objectFit: "contain",
                      objectPosition: "bottom right",
                      transform: "rotate(10deg)",
                      transformOrigin: "bottom right",
                      opacity: 0.88,
                    }}
                  />
                </div>
              );
            })}
          </div>
        </div>

      </div>
    </div>
  );
}
